  function persist(){localStorage.setItem(KEY,JSON.stringify(data));}
  function arr(){return kind==='villageStages'?(data.village.developmentStages||[]):(data[kind]||[]);}
  function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
  function parseMap(text){const out={};String(text||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).forEach(line=>{const [k,v]=line.split(':');if(k)out[k.trim()]=Number(v||0);});return out;}
  function mapText(obj){return Object.entries(obj||{}).map(([k,v])=>`${k}:${v}`).join('\n');}
  function jsonText(obj){return JSON.stringify(obj||[],null,2);}
  function parseJson(text,fallback=[]){try{return JSON.parse(String(text||'').trim()||JSON.stringify(fallback));}catch{throw new Error('JSON invalide dans ce champ.');}}
  function renderList(){
    $('#editorTitle').textContent=titles[kind]||kind;
    $('#editorList').innerHTML=arr().map(x=>`<div class="editor-row"><span>${x.icon||'◌'}</span><div class="grow"><b>${esc(x.name)}</b><small>${esc(x.id)}</small></div><button class="btn" data-edit="${esc(x.id)}">Éditer</button><button class="btn danger" data-del="${esc(x.id)}">×</button></div>`).join('')||'<p class="muted">Aucun élément.</p>';
    $$('[data-edit]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.edit;renderForm(arr().find(x=>x.id===selectedId)||{});});
    $$('[data-del]').forEach(b=>b.onclick=()=>remove(b.dataset.del));
  }
